estyle","Backstroke","Breaststroke"],"exercise_ids":["swimback","swimbreast","swimfly","swimfree"],"buying_tips":"Try a few shapes; the best goggle is the one that seals on your face.","safety":"","group_order":7,"sort_order":24},{"id":"swimkit","name":"Swim training aids","aliases":["Kickboard","Pull buoy","Fins","Hand paddles"],"keywords":"kickboard pull buoy fins paddles swim","category":"Household & outdoor","subcategory":"Water","app_group":"Cardio","tier":1,"setting":"both","description":"Kickboards, pull buoys, fins and paddles that isolate legs or arms or add resistance in the pool.","muscle_focus":["Shoulders","Lats","Legs"],"loading":"Friction","weight_options":"","adjustability":"","footprint":null,"space":"S","price_band":"$","requires":["pool"],"substitutes":[],"signature_exercises":["Kickboard kick sets","Pull buoy freestyle","Paddle sets","Fin drills"],"exercise_ids":["swimfree"],"buying_tips":"Start with small paddles to protect the shoulders.","safety":"Build up paddle use gradually.","group_order":7,"sort_order":25},{"id":"deskelliptic","name":"Under-desk elliptical","aliases":["Seated elliptical","Cubii"],"keywords":"under desk seated elliptical cubii","category":"Elliptical & gliders","subcategory":"Compact ellipticals","app_group":"Cardio","tier":1,"setting":"home","description":"A small pedal-only elliptical you use seated under a desk or chair, for gentle leg movement during the day.","muscle_focus":["Quads","Calves","Glutes"],"loading":"Air / magnetic / fan resistance","weight_options":"Magnetic, ~8 levels","adjustability":"Resistance dial; some motorised.","footprint":{"length_cm":60,"width_cm":45,"height_cm":25},"space":"S","price_band":"$$","requires":[],"substitutes":["pedalexer","ministepper"],"signature_exercises":["Seated elliptical pedalling","Under-desk cycling","Reverse pedalling"],"exercise_ids":[],"buying_tips":"Low and quiet; check your desk height leaves enough knee room.","safety":"","group_order":7,"sort_order":26},{"id":"walk