at","tier":1,"setting":"both","description":"Cloth strips wound around the hands and wrists under gloves to support knuckles and wrists.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"3–5 m (120–180 in)","adjustability":"","footprint":null,"space":"S","price_band":"$","requires":[],"substitutes":["gloves"],"signature_exercises":["Heavy bag rounds","Pad work","Speed bag"],"exercise_ids":["baghook","bagjabcross","bag123","bagpunchout","baguppercut","kickbagrounds","bagrounds"],"buying_tips":"180 in Mexican-style wraps suit most adults; gel wraps are quicker but less supportive.","safety":"Wrap firmly across the knuckles but not tight enough to numb fingers.","group_order":10,"sort_order":5},{"id":"headgear","name":"Headgear","aliases":["Head guard","Sparring helmet"],"keywords":"headgear head guard","category":"Combat","subcategory":"Protective gear","app_group":"Combat","tier":1,"setting":"both","description":"Padded headgear worn for sparring to reduce cuts and bruising.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"S–XL","adjustability":"Adjustable laces or straps.","footprint":null,"space":"S","price_band":"$$","requires":[],"substitutes":[],"signature_exercises":["Sparring","Partner drills"],"exercise_ids":[],"buying_tips":"Check it doesn't block your vision when you tuck your chin.","safety":"It reduces cuts, not concussion risk; spar sensibly.","group_order":10,"sort_order":6},{"id":"kickshield","name":"Kick shield","aliases":["Strike shield","Kick bag shield"],"keywords":"kick shield strike pad","category":"Combat","subcategory":"Pads & targets","app_group":"Combat","tier":1,"setting":"both","description":"A large, thick hand-held pad for full-power kicks, knees and pushes.","muscle_focus":["Legs","Glutes","Core"],"loading":"None (support/tool)","weight_options":"60–80 cm long","adjustability":"","footprint":null,"space":"S","price_band":"$$","requires":[],"substitutes":["thaipads"],"signature_exercises":["Push kicks","Side kicks","Power kicks"],"exercise_ids":[],"buying_tips":"Curved shields absorb more of the kick for the holder.","safety":"","group_order":10,"sort_order":7},{"id":"tatami","name":"Martial arts mats","aliases":["Tatami","Judo mats","Grappling mats","Jigsaw mats"],"keywords":"martial arts mats tatami grappling","category":"Combat","subcategory":"Grappling","app_group":"Combat","tier":1,"setting":"both","description":"Thick foam mats that cushion falls for grappling, throws and floor work.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"Tiles 1×1 m, 2–5 cm thick","adjustability":"Interlocking tiles to any size.","footprint":{"length_cm":300,"width_cm":300,"height_cm":4},"space":"L","price_band":"$$","requires":[],"substitutes":["yogamat"],"signature_exercises":["Breakfalls","Grappling drills","Throws","Ground work"],"exercise_ids":[],"buying_tips":"4 cm is the minimum for throws; jigsaw mats are fine for drilling.","safety":"","group_order":10,"sort_order":8},{"id":"mmagloves","name":"MMA gloves","aliases":["Grappling gloves","Hybrid gloves","Open-finger gloves"],"keywords":"mma gloves","category":"Combat","subcategory":"Protective gear","app_group":"Combat","tier":1,"setting":"both","description":"Thin open-finger gloves that allow grappling as well as striking.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"4–7 oz","adjustability":"","footprint":null,"space":"S","price_band":"$","requires":["wraps"],"substitutes":["gloves"],"signature_exercises":["Ground and pound","MMA bag work","Grappling"],"exercise_ids":[],"buying_tips":"7 oz hybrid gloves are better for sparring than 4 oz fight gloves.","safety":"They give less protection; go lighter on heavy bags.","group_order":10,"sort_order":9},{"id":"mouthguard","name":"Mouthguard","aliases":["Gum shield","Mouth guard"],"keywords":"mouthguard gumshield","category":"Combat","subcategory":"Protective gear","app_group":"Combat","tier":1,"setting":"both","description":"A shaped guard over the teeth to protect them and the jaw during sparring and contact.","muscle_focus":[],"loading":"None (support/tool)","weight_options":"Boil-and-bite or custom","adjustability":"Mouldable.","footprint":null,"space":"S","price_band":"$","requires":[],"substitutes":[],"signature_exercises":["Sparring","Grappling","Contact drills"],"exercise_ids":[],"buying_tips":"Boil-and-bite is fine to start; custom-fit is worth it for regular sparring.","safety":"Wear one for any contact sparring.","group_order":10,"sort_order":10},{"id":"reflexbag","name":"Reflex bag","aliases":["Reflex ball stand","Spinning reflex bar","Boxing reflex ball"],"keywords":"reflex bag ball stand","category":"Combat","subcategory":"Bags","app_group":"Combat","tier":1,"setting":"home","description":"A ball or pad on a spring-loaded stand (or headband) that rebounds quickly for speed and reaction drills.","muscle_focus":["Shoulders","Arms"],"loading":"Spring","weight_options":"Stand 120–170 cm","adjustability":"Height adjustable.","footprint":{"length_cm":50,"width_cm":50,"height_cm":160},"space":"S","price_band":"$$","requires":[],"substitutes":["doubleend","speedbag"],"signature_exercises":["Reflex ball punches","Jab and slip","Rapid combinations"],"exercise_ids":[],"buying_tips":"A weighted base that doesn't tip matters more than the ball.","safety":"","group_order":10,"sort_order":11},{"id":"shinguards","name":"Shin guards","aliases":["Shin pads","Shin and instep guards"],"keywords":"shin guards pads","category":"Combat","subcategory":"Protective gear","app_group":"Combat","tier":1,"setting":"both","description":"Padded guards covering the shin and instep for kicking pads, bags and sparring partners.","muscle_focus":["Legs"],"loading":"None (support/tool)","weight_options":"S–XL","adjustability":"Strap or sleeve fit.","footprint":null,"space":"S","price_band":"$$","requires":[],"substitutes":[],"signature_exercises":["Roundhouse kicks","Checking kicks","Kickboxing sparring"],"exercise_ids