  as r(id text, name text, aliases text[], keywords text, category text, subcategory text, app_group text, group_order smallint, sort_order smallint, tier smallint, setting text, description text, muscle_focus text[], loading text, weight_options text, adjustability text, footprint jsonb, space text, price_band text, requires text[], substitutes text[], signature_exercises text[], exercise_ids text[], buying_tips text, safety text)
on conflict (id) do update set name = excluded.name, aliases = excluded.aliases, keywords = excluded.keywords, category = excluded.category, subcategory = excluded.subcategory, app_group = excluded.app_group, group_order = excluded.group_order, sort_order = excluded.sort_order, tier = excluded.tier, setting = excluded.setting, description = excluded.description, muscle_focus = excluded.muscle_focus, loading = excluded.loading, weight_options = excluded.weight_options, adjustability = excluded.adjustability, footprint = excluded.footprint, space = excluded.space, price_band = excluded.price_band, requires = excluded.requires, substitutes = excluded.substitutes, signature_exercises = excluded.signature_exercises, exercise_ids = excluded.exercise_ids, buying_tips = excluded.buying_tips, safety = excluded.safety;

update public.exercises e set req = v.req
from (values
  ('sealrow', 'barbell,plates,highbench'),
  ('safetybarsquat', 'ssb,plates,powerrack|squatstands|halfrack'),
  ('declinemach', 'declinepressm|plateincline|chestpress'),
