where e.id = v.id;

commit;

select (select count(*) from public.gear) as gear_rows, (select count(*) from public.exercises where req ~ '(^|[,|])(highbench|ssb|pulloverm|yoke|log|tyre)([,|]|$)') as exact_req_rows;
